//! Key succession, audit packs and the completeness check (Genesis Mesh
//! 1.5.0): the shared conformance suite `audit`, generated by the Python
//! reference (genesismesh/conformance/generate_vectors.py) and copied
//! unchanged, run as the reference's `audit_vectors.evaluate` runs it.

use std::collections::{BTreeMap, BTreeSet};

use sha2::Digest;

use genesis_mesh_sdk::{
    audit_pack::{check_completeness, parse_changes, verify_audit_pack, VerifyPackOptions},
    canonical::{parse_timestamp, received_canonical},
    json,
    key_history::{verify_key_history, NaKeyHistory, NaKeys},
    parse_strict_json,
    verify::{
        check_anchors, parse_export_lines, verify_boundary_decision, verify_evidence_events,
        verify_store_anchors, VerifyDecisionOptions, VerifyEvidenceOptions,
    },
    Value,
};

fn suite() -> Value {
    serde_json::from_str(include_str!("fixtures/audit.json")).unwrap()
}

fn history(input: &Value) -> NaKeyHistory {
    verify_key_history(
        &input["genesis"],
        input["successions"].as_array().unwrap(),
        input["root_public_key"].as_str(),
    )
    .history
    .expect("the vector's key history verifies")
}

fn at(value: &Value) -> i64 {
    parse_timestamp(value.as_str().unwrap())
        .unwrap()
        .timestamp_micros()
}

fn changes(rows: &Value) -> Vec<genesis_mesh_sdk::audit_pack::Change> {
    parse_changes(&rows.to_string(), false).unwrap()
}

fn sorted_set(items: impl IntoIterator<Item = String>) -> Value {
    json!(items.into_iter().collect::<BTreeSet<_>>())
}

/// What this crate makes of one vector's input, in the form of `expected`.
fn evaluate(v: &Value) -> Value {
    let input = &v["input"];
    match v["kind"].as_str().unwrap() {
        "canonical_form" => {
            let body = received_canonical(v["model"].as_str().unwrap(), &v["record"]).unwrap();
            let digest: String = sha2::Sha256::digest(body.as_bytes())
                .iter()
                .map(|b| format!("{b:02x}"))
                .collect();
            json!({"canonical": body, "digest": digest})
        }
        "key_history" => {
            let result = verify_key_history(
                &input["genesis"],
                input["successions"].as_array().unwrap(),
                input["root_public_key"].as_str(),
            );
            let keys: Vec<Value> = result
                .history
                .iter()
                .flat_map(|h| h.keys.iter().map(|k| k.to_json()))
                .collect();
            json!({
                "verified": result.verified,
                "failures": result.failures.iter()
                    .map(|f| json!({"key_sequence": f.key_sequence, "reason": f.reason}))
                    .collect::<Vec<_>>(),
                "keys": keys,
            })
        }
        "key_at" => json!({"keys": history(input).keys_at(at(&input["at"]))}),
        "verify_export" => {
            let events = parse_export_lines(input["lines"].as_str().unwrap()).unwrap();
            let options = VerifyEvidenceOptions {
                key_history: Some(history(input)),
                ..VerifyEvidenceOptions::new(
                    Vec::new(),
                    input["executor_keys"].as_array().unwrap().clone(),
                )
            };
            let result = verify_evidence_events(&events, &options);
            json!({"failures": result.failures.iter()
                .map(|f| json!({"store_sequence": f.store_sequence, "reason": f.reason}))
                .collect::<Vec<_>>()})
        }
        "verify_anchors" => {
            let anchors = check_anchors(input["anchors"].as_array().unwrap().clone()).unwrap();
            let keys = NaKeys::History(history(input));
            let sovereign = input["genesis"]["network_name"].as_str();
            let result = verify_store_anchors(&anchors, Some(&keys), sovereign);
            json!({"failures": result.failures.iter()
                .map(|f| json!({"anchor_sequence": f.anchor_sequence, "reason": f.reason}))
                .collect::<Vec<_>>()})
        }
        "decision_at_record_time" => {
            let base = VerifyDecisionOptions {
                key_history: Some(history(input)),
                ..VerifyDecisionOptions::default()
            };
            let archived = VerifyDecisionOptions {
                at_record_time: true,
                ..base.clone()
            };
            let now = VerifyDecisionOptions {
                now: Some(micros_to_time(at(&input["now"]))),
                ..base
            };
            json!({
                "at_record_time": verify_boundary_decision(&input["decision"], &archived).reason,
                "now": verify_boundary_decision(&input["decision"], &now).reason,
            })
        }
        "pack" => {
            let files: BTreeMap<String, Vec<u8>> = input["files"]
                .as_object()
                .unwrap()
                .iter()
                .map(|(path, text)| (path.clone(), text.as_str().unwrap().as_bytes().to_vec()))
                .collect();
            let held = input["held_anchors"]
                .as_array()
                .map(|a| check_anchors(a.clone()).unwrap());
            let mut options =
                VerifyPackOptions::new(input["root_public_key"].as_str().unwrap(), held);
            options.changes = input.get("changes").filter(|c| !c.is_null()).map(changes);
            let result = verify_audit_pack(&files, &options);
            let mut out = json!({
                "verified": result.verified,
                "reasons": result.reasons(),
                "warnings": sorted_set(result.warnings.iter().map(|w| w.reason.clone())),
            });
            if let Some(report) = &result.completeness {
                out["unmatched_changes"] = json!(report["unmatched_changes"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|c| c["index"].clone())
                    .collect::<Vec<_>>());
            }
            out
        }
        "completeness" => {
            let events: Vec<Value> = input["lines"]
                .as_str()
                .unwrap()
                .split('\n')
                .filter(|l| !l.is_empty())
                .map(|l| parse_strict_json(l).unwrap())
                .collect();
            let period = (at(&input["period"][0]), at(&input["period"][1]));
            let report = check_completeness(
                &changes(&input["changes"]),
                &events,
                &[],
                period,
                input["tolerance_seconds"].as_i64().unwrap(),
            );
            let indices = |key: &str| -> Vec<Value> {
                report[key]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|c| c["index"].clone())
                    .collect()
            };
            json!({
                "pairs": report["pairs"].as_array().unwrap().iter()
                    .map(|p| json!([p["change"], p["record_id"], p["matched_by"]]))
                    .collect::<Vec<_>>(),
                "unmatched_changes": indices("unmatched_changes"),
                "outside_period": indices("outside_period"),
                "unmatched_records": report["unmatched_records"].as_array().unwrap().iter()
                    .map(|r| r["record_id"].clone())
                    .collect::<Vec<_>>(),
            })
        }
        other => panic!("unknown vector kind {other}"),
    }
}

fn micros_to_time(at: i64) -> chrono::DateTime<chrono::Utc> {
    chrono::DateTime::from_timestamp_micros(at).unwrap()
}

#[test]
fn every_vector_gives_the_reference_outcome() {
    let suite = suite();
    assert_eq!(suite["suite"], "audit");
    let vectors = suite["vectors"].as_array().unwrap();
    let mut failed = Vec::new();
    for v in vectors {
        let got = evaluate(v);
        if got != v["expected"] {
            failed.push(format!(
                "{}:\n  expected {}\n  got      {got}",
                v["id"], v["expected"]
            ));
        }
    }
    assert!(failed.is_empty(), "{}", failed.join("\n"));
    assert_eq!(vectors.len(), 44);
}
